using System.Collections.Generic;
using UnityEngine;

namespace DnD.Game
{
    /// <summary>
    /// Central sprite lookup. Every sprite in the game is requested by id (e.g. "pc_fighter_down_0", "tile_grass").
    /// 1) If a real art file exists at Assets/Resources/Art/{id}.png it is used (see docs/ART_IMPORT_GUIDE.md).
    /// 2) Otherwise a placeholder is generated by PlaceholderArt.
    /// Swapping in real art therefore never requires code changes.
    /// </summary>
    public static class ArtRegistry
    {
        public const int PixelsPerUnit = 16;
        static readonly Dictionary<string, Sprite> Cache = new Dictionary<string, Sprite>();
        static readonly Dictionary<string, bool> RealCache = new Dictionary<string, bool>();

        /// <summary>Every id asked for since the last ClearCache (used to audit for leftover placeholder art).</summary>
        public static readonly HashSet<string> Requested = new HashSet<string>();

        /// <summary>True if real art for this id ships in Resources/Art (not a generated placeholder).</summary>
        public static bool IsReal(string id)
        {
            if (string.IsNullOrEmpty(id)) return false;
            if (RealCache.TryGetValue(id, out var real)) return real;
            real = Resources.Load<Texture2D>("Art/" + id) != null;
            RealCache[id] = real;
            return real;
        }

        /// <summary>The first id that has real art, else the last one (which then gets a placeholder).</summary>
        public static string Resolve(params string[] ids)
        {
            foreach (var id in ids) if (IsReal(id)) return id;
            return ids[ids.Length - 1];
        }

        public static Sprite Get(string id)
        {
            if (string.IsNullOrEmpty(id)) id = "missing";
            Requested.Add(id);
            if (Cache.TryGetValue(id, out var s)) return s;

            s = Resources.Load<Sprite>("Art/" + id);
            if (s == null)
            {
                var tex = Resources.Load<Texture2D>("Art/" + id);
                if (tex != null)
                {
                    tex.filterMode = FilterMode.Point;
                    s = Sprite.Create(tex, new Rect(0, 0, tex.width, tex.height), new Vector2(0.5f, 0.5f), PixelsPerUnit);
                }
            }
            if (s == null) s = PlaceholderArt.Generate(id);
            s.name = id;
            Cache[id] = s;
            return s;
        }

        /// <summary>Animation frames: {id}_0, {id}_1 ... Falls back to the single {id} sprite.</summary>
        public static Sprite[] Frames(string id, int count)
        {
            var arr = new Sprite[count];
            for (int i = 0; i < count; i++) arr[i] = Get(id + "_" + i);
            return arr;
        }

        public static void ClearCache() { Cache.Clear(); RealCache.Clear(); Requested.Clear(); }
    }
}
